import argparse

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description='Paper VARC training and test-time training')
    parser.add_argument('--resume-checkpoint', type=str, default=None, help='Path to checkpoint to resume training from.')
    parser.add_argument('--resume-skip-task-token', action='store_true', help='Ignore task token embedding weights in the checkpoint when resuming.')
    parser.add_argument('--resume-reset-optimizer', action='store_true', help='Do not load optimizer/scheduler/scaler states when resuming a checkpoint.')
    parser.add_argument('--resume-reset-epoch', action='store_true', help='Ignore the stored epoch in the checkpoint and restart training from epoch 1.')
    parser.add_argument('--use-wandb', action='store_true', help='Log training metrics to Weights & Biases.')
    parser.add_argument('--wandb-project', type=str, default='VisionARC', help='Weights & Biases project name.')
    parser.add_argument('--wandb-run-name', type=str, default='', help='Optional run name for Weights & Biases.')
    parser.add_argument('--no-compile', action='store_true', help='Disable torch.compile optimization (useful for debugging).')
    parser.add_argument('--compile-mode', type=str, default='reduce-overhead', choices=('default', 'reduce-overhead', 'max-autotune'), help="torch.compile mode: 'default' (balanced), 'reduce-overhead' (faster), 'max-autotune' (slowest compile, fastest runtime).")
    parser.add_argument('--no-amp', action='store_true', help='Disable automatic mixed precision training.')
    parser.add_argument('--data-root', type=str, default='raw_data/ARC-AGI')
    parser.add_argument('--train-split', dest='train_split', default='training', help='Dataset split to use for training.')
    parser.add_argument('--eval-split', dest='eval_split', default='training', help="Dataset split to evaluate. Use '' to disable evaluation.")
    parser.add_argument('--eval-subset', dest='eval_subset', choices=('train', 'test'), default='test', help='Which example subset to use when evaluating a split.')
    parser.add_argument('--architecture', type=str, choices=['vit'], default='vit')
    parser.add_argument('--image-size', type=int, default=30)
    parser.add_argument('--num-colors', type=int, default=10)
    parser.add_argument('--embed-dim', type=int, default=256)
    parser.add_argument('--depth', type=int, default=6)
    parser.add_argument('--num-heads', type=int, default=8)
    parser.add_argument('--mlp-dim', type=int, default=512)
    parser.add_argument('--dropout', type=float, default=0.1)
    parser.add_argument('--batch-size', type=int, default=32)
    parser.add_argument('--epochs', type=int, default=10)
    parser.add_argument('--num-task-tokens', type=int, default=1, help='Number of learned task-prefix tokens. Use 0 for a task-token-free dense ViT.')
    parser.add_argument('--lr-scheduler', type=str, default='cosine', choices=('none', 'cosine'))
    parser.add_argument('--lr-min-ratio', type=float, default=0.0, help='Final learning-rate ratio for cosine scheduling. The default 0.0 matches the original VARC schedule; 1.0 gives TRM-style warmup-then-flat scheduling.')
    parser.add_argument('--learning-rate', type=float, default=0.0003)
    parser.add_argument('--weight-decay', type=float, default=0)
    parser.add_argument('--adam-beta1', type=float, default=0.9)
    parser.add_argument('--adam-beta2', type=float, default=0.999)
    parser.add_argument('--max-grad-norm', type=float, default=1.0)
    parser.add_argument('--num-workers', type=int, default=0)
    parser.add_argument('--seed', type=int, default=42)
    parser.add_argument('--save-path', type=str, default=None, help='Optional path to store the final trained checkpoint')
    parser.add_argument('--best-save-path', type=str, default=None, help='Optional path to store the checkpoint achieving the best evaluation accuracy.')
    parser.add_argument('--eval-every', type=int, default=1, help='Evaluate every N epochs when --eval-split is set. Use 1 for every epoch.')
    parser.add_argument('--checkpoint-every', type=int, default=0, help='For offline training, save a resumable checkpoint every N epochs. Use 0 to disable periodic checkpoints.')
    parser.add_argument('--checkpoint-dir', type=str, default=None, help='Directory for --checkpoint-every snapshots. Defaults to the parent directory of --save-path, or outputs/checkpoints.')
    parser.add_argument('--save-ttt-model', action='store_true', help='For test-time training runs, save the final adapted model after TTT. Defaults to outputs/<eval-save-name>_attempt_<n>/final_ttt_model.pt.')
    parser.add_argument('--ttt-model-save-path', type=str, default=None, help='Optional explicit path for --save-ttt-model. For multiple TTT attempts, an attempt suffix is appended before the file extension.')
    parser.add_argument('--ttt-num-each', type=int, default=2)
    parser.add_argument('--ttt-on-the-fly-augmentations', action='store_true', help='For TTT, load the base task once and sample geometry/color augmentations on the fly instead of reading materialized variants.')
    parser.add_argument('--on-the-fly-augmentations', action='store_true', help='Load base ARC tasks and apply geometry/color augmentations on the fly. This is the generic form used by offline pretraining; --ttt-on-the-fly-augmentations remains as a backwards-compatible TTT alias.')
    parser.add_argument('--ttt-virtual-variants-per-epoch', type=int, default=1, help='When --ttt-on-the-fly-augmentations is enabled, repeat each demo sample this many times per epoch with freshly sampled augmentations.')
    parser.add_argument('--virtual-variants-per-epoch', type=int, default=None, help='Generic alias for --ttt-virtual-variants-per-epoch, used by offline augmentation-token pretraining.')
    parser.add_argument('--ttt-eval-augmentations', type=int, default=1, help='When --ttt-on-the-fly-augmentations is enabled, number of sampled task augmentations to evaluate per held-out test sample.')
    parser.add_argument('--eval-augmentations', type=int, default=None, help='Generic alias for --ttt-eval-augmentations, used by offline augmentation-token evaluation.')
    parser.add_argument('--ttt-geometry-set', type=str, choices=('varc_basic', 'dihedral'), default='dihedral', help="Geometry augmentations for on-the-fly TTT. 'dihedral' uses all 8 square symmetries. 'varc_basic' matches the fixed VARC TTT family: identity, 90/180/270 rotations, and vertical/horizontal flips.")
    parser.add_argument('--geometry-set', type=str, choices=('varc_basic', 'dihedral'), default=None, help='Generic alias for --ttt-geometry-set, used by offline augmentation-token pretraining.')
    parser.add_argument('--ttt-augmentation-schedule', type=str, choices=('random', 'fixed'), default='random', help="On-the-fly TTT augmentation schedule. 'random' samples fresh training augmentations continuously. 'fixed' gives each virtual slot a deterministic transform/color map reused for both train and eval, with slot 0 as identity.")
    parser.add_argument('--augmentation-schedule', type=str, choices=('random', 'fixed'), default=None, help="Generic alias for --ttt-augmentation-schedule. Use 'fixed' for a global augmentation-slot schedule shared by train/eval/TTT.")
    parser.add_argument('--ttt-augmentation-task-id-mode', type=str, choices=('base', 'per_variant'), default='base', help='For on-the-fly TTT augmentation datasets, choose whether all augmentations share the base task id or each fixed augmentation slot gets its own normal VARC task id.')
    parser.add_argument('--augmentation-task-id-mode', type=str, choices=('base', 'per_variant'), default=None, help='Generic alias for --ttt-augmentation-task-id-mode, used by offline fixed-augmentation pretraining.')
    parser.add_argument('--ttt-augmentation-seed', type=int, default=12345, help='Seed for deterministic eval augmentations in on-the-fly TTT.')
    parser.add_argument('--augmentation-seed', type=int, default=None, help='Generic alias for --ttt-augmentation-seed, used by offline augmentation-token pretraining.')
    parser.add_argument('--vis-every', type=int, default=25)
    parser.add_argument('--patch-size', type=int, default=2)
    parser.add_argument('--distributed', action='store_true', help='Enable distributed data parallel training (torchrun recommended).')
    parser.add_argument('--disable-translation', action='store_true')
    parser.add_argument('--disable-resolution-augmentation', action='store_true')
    parser.add_argument('--fix-scale-factor', type=int, default=1)
    parser.add_argument('--max-scale-factor', type=int, default=None, help='Optional cap for random resolution augmentation. Leave unset to use the largest scale that fits the canvas.')
    parser.add_argument('--num-attempts', type=int, default=10, help='Number of attempts per evaluation example.')
    parser.add_argument('--eval-save-name', type=str, default=None, help='Name for saving evaluation predictions.')
    return parser.parse_args()
